<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\DcrInitialAccessTokenTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait DcrInitialAccessTokenTenantAccessor
{
    private DcrInitialAccessTokenTenantVO $_tenant;
    public function getTenant(): TenantRef
    {
        return $this->_tenant->value();
    }
    public function tenant(): DcrInitialAccessTokenTenantVO
    {
        return $this->_tenant;
    }
    public function isTenantChanged(?self $original = null): bool
    {
        return !$this->_tenant->equals($original?->_tenant);
    }
    public function withTenant(DcrInitialAccessTokenTenantVO|TenantRef $tenant): self
    {
        $copy = clone $this;
        $copy->_tenant = DcrInitialAccessTokenTenantVO::from($tenant);
        return $copy;
    }
}
